"""rad0041 (VTP44 patch B): bf16_fp8 and bf16_i8 on Flash-Next's geometry. libr4d's gqa8-body units (gqa 12, and gqa 6 with
4-token pages) gain the two layouts' prefill, decode and fused gate+quantiser entry points; one tuple list in r4d_rows.cpp
generates their rows (decode causal or not), checked at compile time against rad_builder.h's RAD_KV_GEOMETRIES; the
Qwen4 expert FP8 plugin reads the layout and geometry tables and its probe offers every layout the table lists for its
geometry. Opt-in through --kv-cache-dtype; the default cache is untouched.
"""
from __future__ import annotations

import re
from bigcherry.patcher import Edit, FilePatch


def _edit(id: str, before: str, after: str, guard: str) -> Edit:
    span = max(4, before.count("\n") + 2)
    return Edit(id=id, anchor=re.escape(before), mode="replace", text=after,
                guard=re.escape(guard), expect_matches=1, max_span_lines=span,
                rationale=("long-anchor: the whole diff hunk is the anchor; " if span > 6 else "")
                + "VTP44 B: bf16 packed KV on Flash-Next")


